"use client";
import { useState } from "react";
export default function AdminSupportInbox({ initialTickets }: { initialTickets: any[] }) { const [tickets, setTickets] = useState(initialTickets); async function update(id: string, status: string) { const response = await fetch("/api/admin/support", { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ id, status }) }); if (!response.ok) return; setTickets((items) => items.map((ticket) => ticket.id === id ? { ...ticket, status } : ticket)); } return <div className="overflow-hidden rounded-2xl border border-slate-800 bg-slate-900 shadow-xl"><div className="border-b border-slate-800 p-5"><h2 className="text-base font-semibold text-white">Support inbox</h2><p className="mt-1 text-xs text-slate-400">Review customer support emails and operational requests.</p></div><div className="divide-y divide-slate-800">{tickets.map((ticket) => <article key={ticket.id} className="p-5"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex items-center gap-2"><h3 className="text-sm font-semibold text-white">{ticket.subject}</h3><span className="rounded-full bg-amber-500/10 px-2 py-1 text-[10px] text-amber-300">{ticket.priority}</span></div><p className="mt-1 text-xs text-slate-500">{ticket.user?.name || ticket.user?.email} · {ticket.category}</p><p className="mt-3 max-w-3xl text-xs leading-5 text-slate-400">{ticket.message}</p></div><div className="flex shrink-0 gap-2"><button onClick={() => update(ticket.id, "IN_PROGRESS")} className="rounded-lg border border-indigo-500/20 px-3 py-2 text-[10px] text-indigo-300">In progress</button><button onClick={() => update(ticket.id, "RESOLVED")} className="rounded-lg border border-emerald-500/20 px-3 py-2 text-[10px] text-emerald-300">Resolve</button></div></div></article>)}{!tickets.length && <p className="p-12 text-center text-xs text-slate-500">No support requests.</p>}</div></div>; }